<?php $esc=function($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}; $totals=(array)($totals??array()); $total=(int)($totals['male']??0)+(int)($totals['female']??0); $levels=array('Preschool','Kindergarten','Grade 1','Grade 2','Grade 3','Grade 4','Grade 5','Grade 6','Grade 7','Grade 8','Grade 9','Grade 10','Grade 11','Grade 12'); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enrollment Details</title><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/dashboard-unified.css" rel="stylesheet"><style>html,body{height:auto!important;overflow-y:auto!important}#wrapper{height:auto!important;min-height:100vh!important;overflow:hidden!important}.content-page,.content{height:auto!important;min-height:100vh!important;overflow:visible!important}.enrollment-shell{padding:20px 15px 28px}.enrollment-hero{padding:30px;color:#fff;border-radius:22px;background:linear-gradient(135deg,#272b8c,#3c40c6)}.enrollment-hero h1{margin:0;color:#fff}.enrollment-hero p{margin:7px 0 0;color:rgba(255,255,255,.8)}.enrollment-card{margin-top:18px;border:0;border-radius:20px;box-shadow:0 16px 38px rgba(15,23,42,.08)}.metric{height:100%;padding:17px;border:1px solid #e7e9f3;border-radius:15px;background:#fff}.metric strong{display:block;color:#272b8c;font-size:1.65rem}.metric span{color:#66708a;font-size:.82rem;font-weight:700}.footer{position:static!important;left:auto!important;right:auto!important}</style></head><body class="dashboard-root-theme"><div id="wrapper"><?php include(__DIR__.'/includes/top-bar.php'); ?><?php include(__DIR__.'/includes/sidebar.php'); ?><div class="content-page"><div class="content"><main class="container-fluid dashboard-shell enrollment-shell"><section class="enrollment-hero"><div class="d-flex flex-wrap justify-content-between align-items-center"><div><h1>Enrollment Details</h1><p>Record enrollee counts by grade level, semester, and sex.</p></div><button class="btn btn-light mt-3 mt-md-0" data-toggle="modal" data-target="#enrollmentModal"><i class="mdi mdi-account-plus-outline"></i> Add Enrollment</button></div></section><div class="row mt-n3 px-2 position-relative" style="z-index:2"><div class="col-md-4 mt-2 px-1"><div class="metric"><strong><?= number_format($total); ?></strong><span>Total Enrollees</span></div></div><div class="col-md-4 mt-2 px-1"><div class="metric"><strong><?= number_format((int)($totals['male']??0)); ?></strong><span>Male Enrollees</span></div></div><div class="col-md-4 mt-2 px-1"><div class="metric"><strong><?= number_format((int)($totals['female']??0)); ?></strong><span>Female Enrollees</span></div></div></div><section class="card enrollment-card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h4 class="mb-0">Recorded Enrollment</h4><button class="btn btn-primary btn-sm" data-toggle="modal" data-target="#enrollmentModal">Add Enrollment</button></div><?php if($this->session->flashdata('success')): ?><div class="alert alert-success"><?= $esc($this->session->flashdata('success')); ?></div><?php endif; ?><?php if($this->session->flashdata('danger')): ?><div class="alert alert-danger"><?= $esc($this->session->flashdata('danger')); ?></div><?php endif; ?><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>School Year</th><th>Semester</th><th>Grade Level</th><th>Male</th><th>Female</th><th>Total</th><th></th></tr></thead><tbody><?php if(empty($enrollments)): ?><tr><td colspan="7" class="text-center text-muted py-4">No enrollment details recorded yet.</td></tr><?php else: foreach($enrollments as $item): ?><tr><td><?= $esc($item->school_year); ?></td><td><?= $esc($item->semester); ?></td><td><?= $esc($item->grade_level); ?></td><td><?= number_format((int)$item->male_count); ?></td><td><?= number_format((int)$item->female_count); ?></td><td><strong><?= number_format((int)$item->male_count+(int)$item->female_count); ?></strong></td><td><a href="<?= base_url(); ?>Page/school_enrollment_delete/<?= (int)$item->id; ?>" class="btn btn-outline-danger btn-sm" onclick="return confirm('Remove this enrollment detail?');"><i class="mdi mdi-delete-outline"></i></a></td></tr><?php endforeach; endif; ?></tbody></table></div></div></section></main></div><?php include(__DIR__.'/includes/footer.php'); ?></div></div><div class="modal fade" id="enrollmentModal"><div class="modal-dialog"><form class="modal-content" method="post" action="<?= base_url(); ?>Page/school_enrollment_save"><div class="modal-header"><h5 class="modal-title">Add Enrollment Details</h5><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body"><div class="form-row"><div class="form-group col-md-6"><label>School Year</label><input class="form-control" name="school_year" required></div><div class="form-group col-md-6"><label>Semester</label><select class="form-control" name="semester"><option>First Semester</option><option>Second Semester</option><option>Annual</option></select></div></div><div class="form-group"><label>Grade Level</label><select class="form-control" name="grade_level" required><option value="">Select Grade Level</option><?php foreach($levels as $level): ?><option><?= $esc($level); ?></option><?php endforeach; ?></select></div><div class="form-row"><div class="form-group col-md-6"><label>Male Enrollees</label><input class="form-control" type="number" min="0" name="male_count" value="0" required></div><div class="form-group col-md-6"><label>Female Enrollees</label><input class="form-control" type="number" min="0" name="female_count" value="0" required></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save Details</button></div></form></div></div><script src="<?= base_url(); ?>assets/js/vendor.min.js"></script><script src="<?= base_url(); ?>assets/js/app.min.js"></script><?php include(__DIR__ . '/includes/school_enrollment_enhancements.php'); ?></body></html>
